function recordModal(id){let b=get(id);if(b.status==='done'){expanded.add(id);tab='done';render();return}let a=(displayIndex.dates.get(today())||[]).find(a=>a.id===id);modal(`<h2>독서 기록</h2><h3>${esc(b.title)}</h3>${a?`<div class="note">오늘의 계획 ${a.from}–${a.to}쪽 · ${a.n}쪽</div>`:''}<p class="small">마지막 기록 ${b.page}쪽 / 전체 ${b.total}쪽<br>입력한 분량은 오늘(${short(today())})에 기록돼요.</p><form id="recordform"><label class="field">지금 어디까지 읽으셨나요?<input name="page" type="number" required min="${b.page}" max="${b.total}" value="${b.page}"></label><p id="error" class="error"></p><button class="primary wide">기록하기</button><button type="button" class="secondary wide add" id="zero">오늘은 안 읽음</button>${cancel}</form>`);const apply=p=>{try{record(state,id,p,today());save();close();render();toast(b.status==='done'?'완독했어요! 기록을 차곡차곡 모아 두었어요.':'진도를 저장하고 남은 일정을 계산했어요.')}catch(e){$('#error').textContent=e.message}};$('#recordform').onsubmit=e=>{e.preventDefault();apply(Number(e.target.page.value))};$('#zero').onclick=()=>apply(b.page)}
function menu(id){let b=get(id);modal(`<h2>${esc(b.title)}</h2>${b.status==='active'?`<button class="menuitem" data-action="edit" data-id="${id}">계획 편집</button><button class="menuitem" data-action="stop" data-id="${id}">읽기 멈추기</button>`:b.status==='past'?`<button class="menuitem" data-action="restart" data-id="${id}">다시 시작</button>`:b.status==='done'?`<button class="menuitem" data-action="edit" data-id="${id}">책 정보 편집</button>`:''}<button class="menuitem danger" data-action="delete" data-id="${id}">완전 삭제</button>${cancel}`)}
function check(){let books=unmet();if(!books.length){toast('모든 진도가 확인되었어요.');return}modal(`<h2>어디까지 읽으셨나요?</h2><p class="small">며칠이 지났어도 마지막 페이지만 한 번 알려 주세요.<br>확인하지 않은 진도는 그대로 유지해요.</p><form id="checkform">${books.map(b=>`<label class="field">${esc(b.title)} · 마지막 ${b.page}쪽<input data-record="${b.id}" type="number" min="${b.page}" max="${b.total}" placeholder="현재 페이지 (선택)"></label>`).join('')}<p id="error" class="error"></p><button class="primary wide">입력한 진도 확인</button><button type="button" id="none" class="secondary wide add">모두 안 읽었어요</button><button type="button" class="cancel" data-action="close">나중에</button></form>`);const submit=none=>{let inputs=[...document.querySelectorAll('[data-record]')],changes=inputs.filter(x=>none||x.value!=='');if(!changes.length){close();return}try{recordMany(state,changes.map(x=>({id:x.dataset.record,page:none?get(x.dataset.record).page:Number(x.value)})),today());save();close();render();toast('확인한 진도를 반영했어요.')}catch(err){$('#error').textContent=err.message}};$('#checkform').onsubmit=e=>{e.preventDefault();submit(false)};$('#none').onclick=()=>submit(true)}
document.addEventListener('click',e=>{let el=e.target.closest('button');if(!el)return;if(el.dataset.tab){if(el.dataset.tab==='calendar'&&tab!=='calendar')resetCalendarDate();tab=el.dataset.tab;render();return}if(el.dataset.date){selected=el.dataset.date;render();return}let id=el.dataset.id,b=get(id);switch(el.dataset.action){case'close':close();break;case'new':form();break;case'edit':form(id);break;case'restart':form(id,true);break;case'record':recordModal(id);break;case'menu':menu(id);break;case'expand':expanded.has(id)?expanded.delete(id):expanded.add(id);render();break;case'prev':case'next':{let d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()+(el.dataset.action==='next'?1:-1));month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();break}case'check':check();break;case'recommend':showRecommendation();break;case'applyrecommend':applyRecommendation();break;case'stop':undo=structuredClone(state);b.status='past';b.reason='직접 중단';recalc(state,ids(b),today());save();close();render();toast('지난 계획으로 이동했어요.',true);break;case'undo':if(undo){state=undo;recommendationCache.key=null;undo=null;save();render();toast('계획을 되돌렸어요.')}break;case'delete':modal(`<h2>완전히 삭제할까요?</h2><p class="small">‘${esc(b.title)}’의 계획과 모든 독서 기록이 삭제돼요. 삭제한 기록은 되돌릴 수 없어요.</p><button class="primary wide" style="background:#a44e40" data-action="confirmdelete" data-id="${id}">완전 삭제</button>${cancel}`);break;case'confirmdelete':{let affected=ids(b);state.books=state.books.filter(x=>x.id!==id);state.records=state.records.filter(x=>x.id!==id);state.alloc=state.alloc.filter(x=>x.id!==id);recalc(state,affected,today());save();close();render();toast('계획과 기록을 삭제했어요.');break}case'backup':backupMenu();break;case'export':exportBackup();break;case'restoreimport':restoreImport();break;case'storagehelp':modal('<h2>독서 정보 저장 안내</h2><p class="small">독서 계획과 기록을 파일로 보관하거나 복원해요.</p><div class="note">이 첫 버전은 현재 기기의 브라우저에 기록을 저장해요. 다른 기기와 동기화되지 않으며, 브라우저 데이터를 지우면 기록도 삭제돼요.</div><button class="primary wide add" data-action="close">알겠어요</button>');break;case'help':if(tab==='timer'){modal('<h2>독서 타이머 사용 안내</h2><p class="small">시간을 내려놓고, 책 속으로.</p><h3>시간 설정과 시작</h3><p class="small">시작 전에 독서 시간을 정하고 중앙 버튼을 눌러 주세요. 설정한 시간이 시계 한 바퀴가 되고, 시작하면 숫자와 설정이 숨겨져요. 부채꼴이 줄어들며 남은 시간을 보여줘요.</p><h3>잠시 쉬거나 다시 설정하기</h3><p class="small">중앙 버튼으로 일시정지하거나 다시 시작할 수 있어요. 시간 다시 설정을 누르면 진행 중인 타이머를 초기화해요. 다른 탭을 보거나 새로고침해도 타이머는 저장된 시간을 기준으로 이어져요.</p><h3>화면 켜짐 유지</h3><p class="small">타이머가 실행 중이고 이 화면을 보고 있을 때 화면이 꺼지지 않도록 요청해요. 일시정지·종료하거나 다른 탭으로 이동하면 해제돼요. 기기·브라우저와 절전 설정에 따라 지원되지 않거나 해제될 수 있어요.</p><p class="small">'+esc($('.timer-lock')?.textContent||'')+'</p><button class="primary wide add" data-action="close">알겠어요</button>');break;}modal('<h2>나의 속도로 읽기</h2><p class="small">① 책마다 목표일 기준 또는 하루 분량 기준을 선택해요.<br>② 달력의 책을 누르고 마지막 읽은 페이지를 입력해요.<br>③ 독서 계획의 책을 누르면 기록 그래프가 펼쳐져요.</p><h3>계획 이동과 편집</h3><p class="small">책 왼쪽 손잡이를 끌어 순서나 읽기 방식을 바꿀 수 있어요. 책 오른쪽 ⋯ 메뉴에서 계획을 편집하거나 읽기를 멈출 수 있어요.</p><p class="small">기록을 확인한 뒤 남은 분량은 다음 날부터 배정해요. 목표일이 오늘이면 남은 분량을 기한 밖에 배정하지 않아요. 더 읽을 시간이 필요하면 목표일을 변경해 주세요. 하루 분량 기준은 목표일 없이 유지돼요.<br>순서대로 읽기에서 하루 분량 책과 다른 책 사이의 전환은 다음 날부터 시작해요.</p><button class="primary wide add" data-action="close">알겠어요</button>');break}});
function reorder(id,target){let list=state.books.filter(b=>b.status==='active'&&b.mode==='sequence').sort((a,b)=>a.order-b.order),a=list.findIndex(b=>b.id===id),z=list.findIndex(b=>b.id===target);if(a<0||z<0||a===z)return;list.splice(z,0,list.splice(a,1)[0]);list.forEach((b,i)=>b.order=i);recalc(state,seqids(),today());save();render();toast('읽는 순서를 바꿨어요.')}
let drag=null,dragFrame=null;
function clearDrag(){drag?.ghost?.remove();drag=null;cancelAnimationFrame(dragFrame);document.body.classList.remove('is-dragging');document.querySelectorAll('.dragging,.drop-target,.drop-before,.drop-after').forEach(x=>x.classList.remove('dragging','drop-target','drop-before','drop-after'))}
function updateDragVisual(){
 if(!drag?.moved)return;
 if(!drag.ghost){const ghost=drag.card.cloneNode(true);ghost.classList.remove('dragging');ghost.classList.add('drag-ghost');ghost.setAttribute('aria-hidden','true');ghost.inert=true;ghost.querySelector('.graphbox')?.remove();Object.assign(ghost.style,{width:drag.width+'px',left:'0',top:'0'});document.body.append(ghost);drag.ghost=ghost;drag.card.classList.add('dragging');document.body.classList.add('is-dragging')}
 drag.ghost.style.transform='translate3d('+(drag.x-drag.offsetX)+'px,'+(drag.y-drag.offsetY)+'px,0) rotate(1deg)';
 document.querySelectorAll('.drop-target,.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after'));
 const target=document.elementFromPoint(drag.x,drag.y),group=target?.closest('[data-group]');if(!group)return;
 group.classList.add('drop-target');const book=target.closest('[data-book]'),source=drag.card.closest('[data-group]');
 if(group===source&&group.dataset.group==='sequence'&&book&&book!==drag.card){const cards=[...group.querySelectorAll('[data-book]')];book.classList.add(cards.indexOf(drag.card)<cards.indexOf(book)?'drop-after':'drop-before')}
 else if(group!==source){const cards=[...group.querySelectorAll('[data-book]')];cards.at(-1)?.classList.add('drop-after')}
}
function dragScroll(){if(!drag)return;if(drag.moved){const edge=90,y=drag.y;let amount=y<edge?-10:y>innerHeight-edge?10:0;if(amount)window.scrollBy(0,amount);updateDragVisual()}dragFrame=requestAnimationFrame(dragScroll)}
document.addEventListener('pointerdown',e=>{let h=e.target.closest('[data-handle]');if(h&&e.isPrimary!==false&&e.button===0){const card=h.closest('.book'),rect=card.getBoundingClientRect();drag={id:h.dataset.handle,card,width:rect.width,offsetX:e.clientX-rect.left,offsetY:e.clientY-rect.top,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};h.setPointerCapture(e.pointerId);dragFrame=requestAnimationFrame(dragScroll)}});
document.addEventListener('pointermove',e=>{if(!drag)return;drag.x=e.clientX;drag.y=e.clientY;drag.moved ||= Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>8;updateDragVisual()});
document.addEventListener('pointerup',e=>{if(!drag)return;let target=document.elementFromPoint(e.clientX,e.clientY),group=target?.closest('[data-group]'),book=target?.closest('[data-book]'),id=drag.id,moved=drag.moved;clearDrag();if(!moved||!group)return;let b=get(id),dest=group.dataset.group,source=b.status==='past'?'past':b.mode;if(dest===source){if(dest==='sequence'&&book)reorder(id,book.dataset.book);return}if(b.status==='past'&&dest!=='past'){form(id,true,dest);return}undo=structuredClone(state);moveBook(state,id,dest,today());save();render();toast(dest==='past'?'지난 계획으로 이동했어요.':'읽기 방식을 변경했어요.',true)});
document.addEventListener('pointercancel',clearDrag);
document.addEventListener('keydown',e=>{let h=e.target.closest('[data-handle]');if(!h||get(h.dataset.handle)?.status!=='active'||get(h.dataset.handle)?.mode!=='sequence'||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();let arr=state.books.filter(b=>b.status==='active'&&b.mode==='sequence').sort((a,b)=>a.order-b.order),i=arr.findIndex(b=>b.id===h.dataset.handle),target=arr[i+(e.key==='ArrowUp'?-1:1)];if(target)reorder(h.dataset.handle,target.id)});
function resetCalendarDate(){selected=today();month=selected.slice(0,7)}
render();if(unmet().length)check();document.addEventListener('visibilitychange',()=>{if(!document.hidden){resetCalendarDate();render()}});
if(typeof window!=='undefined')window.addEventListener('pageshow',e=>{if(e.persisted){resetCalendarDate();render()}});

